import React, { useState, useEffect, useMemo } from 'react';
import { MarketInsight, Category, CompletionStatus, SortMode } from './types';
import { CATEGORIES, INITIAL_INSIGHTS } from './constants';
import MarketCard from './components/MarketCard';
import InsightForm from './components/InsightForm';
import { Plus, LayoutGrid, Clock, Calendar, Hash, ListFilter, CalendarDays, Archive } from 'lucide-react';
import MarketDashboard from './components/MarketDashboard';
import { generateMarketSummary } from './services/geminiService';

const App: React.FC = () => {
  const [insights, setInsights] = useState<MarketInsight[]>(() => {
    const saved = localStorage.getItem('trading_journal_v2');
    return saved ? JSON.parse(saved) : INITIAL_INSIGHTS;
  });

  const [activeCategory, setActiveCategory] = useState<Category>('全部');
  const [selectedMonth, setSelectedMonth] = useState<string | null>(null);
  const [sortMode, setSortMode] = useState<SortMode>('category');
  const [showForm, setShowForm] = useState(false);
  const [editingInsight, setEditingInsight] = useState<MarketInsight | undefined>(undefined);
  const [isGeneratingAI, setIsGeneratingAI] = useState(false);
  const [aiSummary, setAiSummary] = useState('');

  useEffect(() => {
    localStorage.setItem('trading_journal_v2', JSON.stringify(insights));
  }, [insights]);

  const timelineGroups = useMemo(() => {
    const groups: { [key: string]: number } = {};
    insights.forEach(i => {
      const date = new Date(i.updatedAt);
      const key = `${date.getFullYear()}年${date.getMonth() + 1}月`;
      groups[key] = (groups[key] || 0) + 1;
    });
    return Object.entries(groups).sort((a, b) => b[0].localeCompare(a[0]));
  }, [insights]);

  const filteredInsights = useMemo(() => {
    let result = insights;
    if (activeCategory !== '全部') {
      result = result.filter(i => i.category === activeCategory);
    }
    if (selectedMonth) {
      result = result.filter(i => {
        const date = new Date(i.updatedAt);
        return `${date.getFullYear()}年${date.getMonth() + 1}月` === selectedMonth;
      });
    }
    return result;
  }, [insights, activeCategory, selectedMonth]);

  const { activeItems, archivedItems } = useMemo(() => {
    return {
      activeItems: filteredInsights.filter(i => i.completionStatus === '进行中'),
      archivedItems: filteredInsights.filter(i => i.completionStatus !== '进行中')
    };
  }, [filteredInsights]);

  const groupedActiveInsights = useMemo(() => {
    const groups: { [label: string]: MarketInsight[] } = {};
    activeItems.forEach(insight => {
      let label = sortMode === 'timeline' 
        ? new Date(insight.updatedAt).toLocaleDateString('zh-CN', { year: 'numeric', month: 'long', day: 'numeric' })
        : insight.category;
      if (!groups[label]) groups[label] = [];
      groups[label].push(insight);
    });
    const entries = Object.entries(groups);
    return sortMode === 'category' 
      ? entries.sort((a, b) => CATEGORIES.indexOf(a[0] as any) - CATEGORIES.indexOf(b[0] as any))
      : entries.sort((a, b) => b[1][0].updatedAt - a[1][0].updatedAt);
  }, [activeItems, sortMode]);

  const handleSaveInsight = (data: Partial<MarketInsight>) => {
    if (editingInsight) {
      setInsights(prev => prev.map(i => i.id === editingInsight.id ? { ...i, ...data, updatedAt: data.updatedAt || i.updatedAt } as MarketInsight : i));
    } else {
      const newInsight: MarketInsight = {
        id: Math.random().toString(36).substr(2, 9),
        ...data as any,
        updatedAt: data.updatedAt || Date.now(),
        completionStatus: data.completionStatus || '进行中',
      };
      setInsights(prev => [newInsight, ...prev]);
    }
    setShowForm(false);
    setEditingInsight(undefined);
  };

  const handleDeleteInsight = (id: string) => {
    if (window.confirm('确定要删除这条市场记录吗？')) {
      setInsights(prev => prev.filter(i => i.id !== id));
    }
  };

  const handleToggleStatus = (id: string) => {
    const statuses: CompletionStatus[] = ['进行中', '已完成', '已失效'];
    setInsights(prev => prev.map(i => {
      if (i.id === id) {
        const currentIndex = statuses.indexOf(i.completionStatus);
        return { ...i, completionStatus: statuses[(currentIndex + 1) % statuses.length] };
      }
      return i;
    }));
  };

  const handleGenerateAI = async () => {
    setIsGeneratingAI(true);
    const summary = await generateMarketSummary(insights);
    setAiSummary(summary || "分析完成。");
    setIsGeneratingAI(false);
  };

  return (
    <div className="min-h-screen flex flex-col selection:bg-red-100 selection:text-red-900 bg-[#fbfbfb]">
      {/* 头部导航 - 移除了 sticky top-0 以满足不跟随屏幕移动的需求 */}
      <header className="bg-white px-8 py-8">
        <div className="max-w-[1600px] mx-auto space-y-10">
          <div className="flex justify-between items-center">
            <div className="flex items-center gap-4">
              <div className="bg-gray-900 p-3 rounded-[1.25rem] shadow-xl shadow-gray-200">
                <LayoutGrid className="w-5 h-5 text-white" />
              </div>
              <div>
                <h1 className="text-xl font-black text-gray-900 tracking-tight leading-none mb-1">市场周刊</h1>
                <p className="text-[10px] text-gray-400 font-black uppercase tracking-[0.2em]">Market Weekly</p>
              </div>
            </div>

            <button 
              onClick={() => { setEditingInsight(undefined); setShowForm(true); }}
              className="bg-red-500 text-white px-7 py-3.5 rounded-2xl hover:bg-red-600 transition-all flex items-center gap-2.5 shadow-2xl shadow-red-200 font-black text-sm active:scale-95 group"
            >
              <Plus className="w-4 h-4 transition-transform group-hover:rotate-90" />
              <span>新观点</span>
            </button>
          </div>

          {/* 类别导航 - 匹配参考图中的黑色药丸 + 贯穿线风格 */}
          <div className="relative flex items-center w-full gap-4">
            <nav className="flex items-center gap-3 relative z-10">
              {CATEGORIES.map(cat => (
                <button
                  key={cat}
                  onClick={() => setActiveCategory(cat)}
                  className={`px-8 py-3 rounded-2xl text-[14px] font-black transition-all whitespace-nowrap active:scale-95 border-2 ${
                    activeCategory === cat 
                      ? 'bg-gray-900 text-white border-gray-900 shadow-xl shadow-gray-300' 
                      : 'bg-white text-gray-400 border-transparent hover:text-gray-900'
                  }`}
                >
                  {cat}
                </button>
              ))}
            </nav>
            {/* 贯穿线 */}
            <div className="flex-grow h-[1px] bg-gray-100 mt-1"></div>
          </div>
        </div>
      </header>

      <div className="max-w-[1600px] mx-auto px-8 py-6 w-full flex flex-col lg:flex-row gap-16">
        <aside className="lg:w-64 space-y-12 flex-shrink-0">
          <div>
            <div className="flex items-center gap-2.5 mb-8 px-1">
              <Clock className="w-4 h-4 text-gray-400" />
              <h3 className="text-[12px] font-black text-gray-400 uppercase tracking-[0.2em]">时间归档</h3>
            </div>
            <div className="space-y-3">
              <button
                onClick={() => setSelectedMonth(null)}
                className={`w-full text-left px-5 py-4 rounded-2xl text-[13px] font-black transition-all flex items-center justify-between group border-2 ${
                  selectedMonth === null ? 'bg-white border-gray-900 shadow-xl shadow-gray-100 text-gray-900' : 'bg-transparent border-transparent text-gray-400 hover:text-gray-900 hover:bg-white hover:border-gray-100'
                }`}
              >
                <span className="flex items-center gap-3">
                  <Hash className={`w-4 h-4 ${selectedMonth === null ? 'text-red-500' : 'text-gray-300'}`} />
                  所有时间
                </span>
                <span className={`text-[11px] px-2 py-0.5 rounded-lg font-black ${selectedMonth === null ? 'bg-red-50 text-red-500' : 'bg-gray-100 text-gray-400'}`}>
                  {insights.length}
                </span>
              </button>
              {timelineGroups.map(([month, count]) => (
                <button
                  key={month}
                  onClick={() => setSelectedMonth(month)}
                  className={`w-full text-left px-5 py-4 rounded-2xl text-[13px] font-black transition-all flex items-center justify-between group border-2 ${
                    selectedMonth === month ? 'bg-white border-gray-900 shadow-xl shadow-gray-100 text-gray-900' : 'bg-transparent border-transparent text-gray-400 hover:text-gray-900 hover:bg-white hover:border-gray-100'
                  }`}
                >
                  <span className="flex items-center gap-3">
                    <Calendar className={`w-4 h-4 ${selectedMonth === month ? 'text-red-500' : 'text-gray-300'}`} />
                    {month}
                  </span>
                  <span className={`text-[11px] px-2 py-0.5 rounded-lg font-black ${selectedMonth === month ? 'bg-red-50 text-red-500' : 'bg-gray-100 text-gray-400'}`}>
                    {count}
                  </span>
                </button>
              ))}
            </div>
          </div>
        </aside>

        <main className="flex-grow">
          <MarketDashboard 
            insights={insights} 
            onGenerateAI={handleGenerateAI} 
            isGeneratingAI={isGeneratingAI} 
            aiSummary={aiSummary} 
          />

          <div className="flex flex-col sm:flex-row sm:items-end justify-between gap-8 mb-16">
            <div className="space-y-3">
              <p className="text-[12px] font-black text-red-500 uppercase tracking-[0.4em]">Current Insights</p>
              <h2 className="text-4xl font-black text-gray-900 tracking-tight italic">
                保持专注，记录市场的每一次心跳。
              </h2>
            </div>

            <div className="flex bg-gray-100 p-1.5 rounded-2xl items-center border border-gray-100">
              <button onClick={() => setSortMode('category')} className={`px-6 py-3 rounded-xl text-[11px] font-black transition-all ${sortMode === 'category' ? 'bg-white text-gray-900 shadow-lg border border-gray-50' : 'text-gray-400 hover:text-gray-600'}`}>
                <ListFilter className="w-3.5 h-3.5 mr-2 inline" /> 类别
              </button>
              <button onClick={() => setSortMode('timeline')} className={`px-6 py-3 rounded-xl text-[11px] font-black transition-all ${sortMode === 'timeline' ? 'bg-white text-gray-900 shadow-lg border border-gray-50' : 'text-gray-400 hover:text-gray-600'}`}>
                <CalendarDays className="w-3.5 h-3.5 mr-2 inline" /> 时间
              </button>
            </div>
          </div>

          {activeItems.length > 0 ? (
            <div className="space-y-24">
              {groupedActiveInsights.map(([groupLabel, groupItems]) => (
                <section key={groupLabel}>
                  <div className="flex items-center gap-6 mb-12 py-4">
                    <div className="px-6 py-2.5 bg-gray-900 text-white rounded-2xl shadow-xl shadow-gray-200">
                      <span className="text-[13px] font-black">{groupLabel}</span>
                    </div>
                    <div className="h-[2px] flex-grow bg-gradient-to-r from-gray-200 to-transparent"></div>
                  </div>
                  <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-2 gap-x-12 gap-y-16">
                    {groupItems.map(insight => (
                      <MarketCard 
                        key={insight.id} 
                        insight={insight} 
                        onEdit={(i) => { setEditingInsight(i); setShowForm(true); }}
                        onDelete={handleDeleteInsight}
                        onToggleStatus={handleToggleStatus}
                      />
                    ))}
                  </div>
                </section>
              ))}
            </div>
          ) : (
            <div className="text-center py-48 bg-white rounded-[4rem] border border-dashed border-gray-200 shadow-sm">
              <div className="w-20 h-20 bg-gray-50 rounded-full flex items-center justify-center mx-auto mb-6">
                <Plus className="w-8 h-8 text-gray-300" />
              </div>
              <h3 className="text-2xl font-black text-gray-900 mb-2">暂无活跃市场观点</h3>
              <p className="text-sm text-gray-400 max-w-xs mx-auto">现在就去创建你的第一条市场记录，开启专业交易日志之旅。</p>
            </div>
          )}

          {archivedItems.length > 0 && (
            <div className="mt-40 space-y-12">
               <div className="flex items-center gap-6 border-t border-gray-100 pt-24 mb-12">
                  <Archive className="w-7 h-7 text-gray-300" />
                  <h3 className="text-2xl font-black text-gray-300 tracking-tight">已归档的历史回顾</h3>
               </div>
              <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-2 gap-x-12 gap-y-16">
                {archivedItems.map(insight => (
                  <MarketCard 
                    key={insight.id} 
                    insight={insight} 
                    onEdit={(i) => { setEditingInsight(i); setShowForm(true); }}
                    onDelete={handleDeleteInsight}
                    onToggleStatus={handleToggleStatus}
                  />
                ))}
              </div>
            </div>
          )}
        </main>
      </div>

      <footer className="mt-auto border-t border-gray-100 py-20 bg-white text-center">
          <p className="text-[11px] text-gray-300 font-black uppercase tracking-[0.6em]">Trading Journal Pro · Digital Assets Intelligence · 2025</p>
      </footer>

      {showForm && (
        <InsightForm 
          initialData={editingInsight}
          onSave={handleSaveInsight}
          onCancel={() => { setShowForm(false); setEditingInsight(undefined); }}
        />
      )}
    </div>
  );
};

export default App;

import React from 'react';
import { MarketInsight, AssetStatus } from '../types';
import { Edit2, Trash2, Calendar, CheckCircle2, AlertCircle, Activity, Target, Check, X } from 'lucide-react';

interface MarketCardProps {
  insight: MarketInsight;
  onEdit: (insight: MarketInsight) => void;
  onDelete: (id: string) => void;
  onToggleStatus?: (id: string) => void;
}

const getAssetStatusStyle = (status: AssetStatus) => {
  switch (status) {
    case '看涨': return {
      color: 'bg-red-50 text-red-600 border-red-100',
      accent: 'border-red-400',
      icon: <Activity className="w-3.5 h-3.5" />
    };
    case '看跌': return {
      color: 'bg-green-50 text-green-600 border-green-100',
      accent: 'border-green-400',
      icon: <Activity className="w-3.5 h-3.5" />
    };
    case '震荡': return {
      color: 'bg-blue-50 text-blue-600 border-blue-100',
      accent: 'border-blue-400',
      icon: <Activity className="w-3.5 h-3.5" />
    };
    default: return {
      color: 'bg-gray-50 text-gray-500 border-gray-100',
      accent: 'border-gray-200',
      icon: <Activity className="w-3.5 h-3.5" />
    };
  }
};

const MarketCard: React.FC<MarketCardProps> = ({ insight, onEdit, onDelete, onToggleStatus }) => {
  const date = new Date(insight.updatedAt).toLocaleDateString('zh-CN', {
    month: 'long',
    day: 'numeric'
  });

  const completionStatus = insight.completionStatus;
  const { color, icon, accent } = getAssetStatusStyle(insight.status);

  const getCardStyle = () => {
    switch (completionStatus) {
      case '已完成': return 'bg-white border-gray-100 opacity-90';
      case '已失效': return 'bg-gray-50/50 border-gray-200 grayscale opacity-80';
      default: return 'bg-white border-gray-100 shadow-[0_20px_60px_-15px_rgba(0,0,0,0.03)] hover:shadow-[0_40px_80px_-20px_rgba(0,0,0,0.08)] hover:-translate-y-1';
    }
  };

  const getTagStyle = () => {
    switch (completionStatus) {
      case '已完成': return 'bg-emerald-500 text-white';
      case '已失效': return 'bg-slate-400 text-white';
      default: return 'bg-red-500 text-white';
    }
  };

  const getStatusIcon = () => {
    switch (completionStatus) {
      case '已完成': return <CheckCircle2 className="w-3 h-3" />;
      case '已失效': return <AlertCircle className="w-3 h-3" />;
      default: return <Activity className="w-3 h-3" />;
    }
  };

  return (
    <div className={`group relative mt-6 border rounded-[3rem] p-10 pt-12 transition-all duration-500 flex flex-col min-h-[480px] ${getCardStyle()}`}>

      {/* 状态标签 - 浮动在卡片左上方 */}
      <div className="absolute -top-4 left-10 flex gap-2 z-20">
        <button 
          onClick={() => onToggleStatus?.(insight.id)}
          className={`flex items-center gap-2 px-5 py-2.5 rounded-full text-[12px] font-black tracking-widest shadow-xl transition-all active:scale-95 hover:brightness-110 cursor-pointer ${getTagStyle()}`}
        >
          {getStatusIcon()}
          {completionStatus}
        </button>
      </div>

      {/* 背景水印 */}
      <div className="absolute inset-0 flex items-center justify-center pointer-events-none opacity-[0.02] overflow-hidden rounded-[3rem]">
        {completionStatus === '已完成' && <Check className="w-80 h-80" />}
        {completionStatus === '已失效' && <X className="w-80 h-80" />}
        {completionStatus === '进行中' && <Activity className="w-80 h-80" />}
      </div>

      {/* 头部：代码 + 日期 + 行情状态 */}
      <div className="relative z-10 flex justify-between items-start mb-10">
        <div>
          <h3 className="text-5xl font-black text-gray-900 tracking-tighter mb-2">{insight.symbol}</h3>
          <div className="flex items-center text-[13px] text-gray-400 gap-2 font-bold ml-1">
            <Calendar className="w-4 h-4 opacity-50" />
            {date}
          </div>
        </div>
        <div className={`px-6 py-2.5 rounded-2xl text-[14px] font-black border flex items-center gap-2.5 shadow-sm ${color}`}>
          {insight.status}
          {icon}
        </div>
      </div>

      {/* 内容区域 */}
      <div className="relative z-10 space-y-8 flex-grow">
        {/* 核心观察 */}
        <div className="space-y-3">
          <p className="text-[11px] font-black uppercase tracking-[0.25em] text-gray-400 ml-1">核心观察</p>
          <div className="p-1 pr-4">
             <p className="text-[16px] leading-relaxed font-bold text-gray-700">
               {insight.focusPoints}
             </p>
          </div>
        </div>

        {/* 入场参考 */}
        {insight.entryLevel && (
          <div className="flex items-center justify-between p-6 px-8 rounded-3xl border border-dashed bg-gray-50 border-gray-200">
            <p className="text-[12px] font-black uppercase tracking-widest text-gray-400">入场参考</p>
            <div className="flex items-center gap-3">
              <Target className="w-5 h-5 text-red-400" />
              <p className="text-2xl font-black tracking-tighter text-gray-900">{insight.entryLevel}</p>
            </div>
          </div>
        )}

        {/* 执行策略 */}
        <div className="space-y-3">
           <p className="text-[11px] font-black uppercase tracking-[0.25em] text-gray-400 ml-1">执行策略</p>
           <div className={`p-8 rounded-[2rem] border-l-[10px] bg-sky-50/40 border-sky-100 ${accent} transition-all`}>
            <p className="text-[17px] font-black leading-relaxed text-gray-900">
              {insight.strategy}
            </p>
          </div>
        </div>
      </div>

      {/* 操作按钮 */}
      <div className="relative z-10 mt-8 pt-8 border-t border-gray-100/60 flex justify-end items-center gap-3 opacity-0 group-hover:opacity-100 transition-all duration-300">
        <button 
          onClick={() => onEdit(insight)}
          className="px-5 py-2.5 text-gray-400 hover:text-gray-900 hover:bg-gray-100 rounded-2xl transition-all flex items-center gap-2 text-[13px] font-black"
        >
          <Edit2 className="w-4 h-4" />
          编辑
        </button>
        <button 
          onClick={() => onDelete(insight.id)}
          className="px-5 py-2.5 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-2xl transition-all flex items-center gap-2 text-[13px] font-black"
        >
          <Trash2 className="w-4 h-4" />
          删除
        </button>
      </div>
    </div>
  );
};

export default MarketCard;
